using System;

interface ICounter { void Inc(); int Val { get; } }
struct Counter : ICounter {
    public int Val { get; private set; }
    public void Inc() => Val++;
}

class Program {
    static void Main() {
        Counter c = new Counter();
        ICounter ic = c;
        ic.Inc();
        Console.WriteLine($"{c.Val}:{ic.Val}");
    }
}

using System;

class Program {
    static string Classify(object o) => o switch {
        int n when n > 10 => "Big",
        int => "Small",
        string s => $"Str({s.Length})",
        _ => "Other"
    };
    static void Main() {
        Console.WriteLine($"{Classify(15)}-{Classify(4)}-{Classify("Hi")}");
    }
}

